'use strict';const M=Model,U=OmniUI,$=x=>document.getElementById(x);window.OMNI_PREVIEW=!window.omnibloomHost;let s=null,busy=false,selected=null,epoch=0,mock={version:1,revision:0,blockThirdParty:true,canBlockThirdParty:true,sites:[{origin:'https://example.org',bytes:245760,cookies:4,canClear:true},{origin:'https://video.example',bytes:1458176,cookies:2,canClear:true}]};function draw(){$('refresh').disabled=busy;const list=$('list');list.replaceChildren();$('third').checked=!!s?.blockThirdParty;$('third').disabled=busy||!s?.canBlockThirdParty;for(const x of s?.sites||[]){if(!x.origin.includes($('query').value.toLowerCase()))continue;const c=document.createElement('article');c.className='tile';const h=document.createElement('h2');h.textContent=new URL(x.origin).hostname;const p=document.createElement('p');p.textContent=x.origin+' · '+(x.bytes/1024).toFixed(1)+' KiB · '+x.cookies+' cookies';const btn=document.createElement('button');btn.textContent='Clear data';btn.disabled=busy||!x.canClear;btn.onclick=()=>{selected=x.origin;$('origin').textContent=selected;$('error').textContent='';U.modal('confirm')};c.append(h,p,btn);list.append(c)}if(!list.children.length)list.textContent=s?'No sites match.':'Site data is unavailable.'}function foreignModal(allowed){return [...document.querySelectorAll('dialog[open],[role=dialog]:not([hidden])')].some(e=>e!==allowed&&e.getClientRects().length)}
function usable(e){return e&&e.isConnected&&!e.disabled&&!e.closest('[hidden],[inert]')&&e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden'}
async function load(){if(busy)return;const e=++epoch;try{const next=M.validate(await U.request('siteData.list',{},()=>mock));if(e!==epoch)return;if(s&&next.revision<s.revision){U.notify('Older site data ignored. Refresh to try again.');return}s=next;U.notify(window.OMNI_PREVIEW?'Preview data · no real cookies are changed.':'Site data refreshed.')}catch(_){if(e!==epoch)return;U.notify(s?'Could not refresh site data; previous view retained.':'Could not read site data.')}draw()}
async function mutate(type,value){if(busy||!s)return;const before=s,ownedPolicy=type==='policy'&&document.activeElement===$('third')&&!foreignModal(null),confirm=$('confirm'),ownedClear=type==='clear'&&!confirm.hidden&&selected===value;busy=true;epoch++;if(ownedPolicy){$('status').tabIndex=0;U.focus($('status'))}draw();try{const params=type==='clear'?M.clear(before,value):M.policy(before,value);const n=M.validate(await U.request(type==='clear'?'siteData.clear':'siteData.setCookiePolicy',params,()=>{mock={...mock,revision:mock.revision+1,...(type==='clear'?{sites:mock.sites.filter(x=>x.origin!==value)}:{blockThirdParty:value})};return mock}));if(n.revision<=before.revision||type==='policy'&&n.blockThirdParty!==value)throw Error();epoch++;s=n;if(ownedClear&&!confirm.hidden&&selected===value&&!foreignModal(confirm))U.close();U.notify(window.OMNI_PREVIEW?'Preview updated.':'Site data settings updated.')}catch(_){epoch++;$('error').textContent='The change was not confirmed. Refresh before retrying.';U.notify('Change not confirmed; previous view retained.')}finally{busy=false;draw();if(ownedPolicy&&document.activeElement===$('status')&&!foreignModal(null)&&usable($('third')))U.focus($('third'))}}
$('clear').onclick=()=>mutate('clear',selected);$('third').onchange=()=>mutate('policy',$('third').checked);$('query').oninput=draw;$('refresh').onclick=load;load();U.focus($('refresh'));
